INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("2019/07/31 12:00:00", 0.0, 0.0, 10021, 1, 24015, 4, 4, "あうぅ～残念さ～\nマジムンに魂を\n奪われちゃったかな～？", "カオリ（サマー）", 24, 110501, "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("2019/07/31 12:00:00", 0.0, 0.0, 10021, 2, 24016, 4, 1, "今日は踊りのキレも悪いよ～\nゴーヤーっぽいもの食べて、元気回復さ～！", "カオリ（サマー）", 24, 110501, "2030/12/17 14:59:59", 4.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("2019/07/31 12:00:00", 0.0, 0.0, 10021, 3, 24017, 4, 4, "マジムンだらけで目が回るさ～！\nふらふらさ～！", "カオリ（サマー）", 24, 110501, "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("2019/07/31 12:00:00", 0.0, 0.0, 10021, 4, 24018, 1, 2, "なんくるない、なんくるない\n次、頑張ればいいんだよ～！\n海で泳いで\nリフレッシュするさー！", "カオリ（サマー）", 24, 110501, "2030/12/17 14:59:59", 5.2);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("2019/07/31 12:00:00", 0.0, 0.0, 10021, 5, 24019, 5, 6, "恥ずかしいところ\n見られちゃったね～\n水着？　水着のことじゃないよー？", "カオリ（サマー）", 24, 110501, "2030/12/17 14:59:59", 4.2);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("2019/07/31 12:00:00", 0.0, 0.0, 10021, 6, 24020, 2, 2, "絶好調さ～！　この調子で\n海の平和を取り戻すよ～！\n楽しい夏が待ってるさ～！", "カオリ（サマー）", 24, 110501, "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("2019/07/31 12:00:00", 0.0, 0.0, 10021, 7, 24021, 1, 6, "何匹で襲ってきたって\n私はマブイを落っことさないよ～！\nくしゅん！　あ……\n今のくしゃみで落っこちたかも～？", "カオリ（サマー）", 24, 110501, "2030/12/17 14:59:59", 6.4);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("2019/07/31 12:00:00", 0.0, 0.0, 10021, 8, 24022, 2, 2, "ひーやーさーさー♪\n戦いの後は、踊りを踊って\n気分スッキリさ～！", "カオリ（サマー）", 24, 110501, "2030/12/17 14:59:59", 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("2019/07/31 12:00:00", 0.0, 0.0, 10021, 9, 24023, 6, 3, "あれ～？　戦ってるうちに\n水着がどっか行っちゃった～？\nねぇキミ、どっかで見なかった～？\nなんで離れるさ～？", "カオリ（サマー）", 24, 110501, "2030/12/17 14:59:59", 10.08);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("2019/07/31 12:00:00", 0.0, 0.0, 10021, 10, 24024, 1, 2, "まだまだ私は元気だよ～！\nマジムンでもなんでも、\nどんとこーいさー♪", "カオリ（サマー）", 24, 110501, "2030/12/17 14:59:59", 5.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("2019/07/31 12:00:00", 0.0, 0.0, 10021, 11, 24025, 2, 2, "私の空手は世界最強さ～！\n夏の陽射しと青い海も合わされば、\n向かうところ敵なしだよー！", "カオリ（サマー）", 24, 110501, "2030/12/17 14:59:59", 0.0);
